"""Generate a clearly labeled browser fixture for reviewing real combat geometry."""
from pathlib import Path
p=Path(__file__).resolve().parent.parent
scripts='\n'.join((p/'src'/name).read_text() for name in ['strings.js','content.js','sim.js','render.js'])
html='''<!doctype html><html><head><meta charset="utf-8"><title>SWARMWAR combat fixtures</title><style>html,body{margin:0;background:#071218;color:#dfefee;font:12px system-ui;overflow:hidden}canvas{position:fixed;inset:0;width:100%;height:100%}nav{position:fixed;z-index:2;top:12px;left:12px;display:flex;gap:6px;align-items:center;padding:10px;border:1px solid #accbd533;border-radius:17px;background:#0c1924e8;flex-wrap:wrap;max-width:92vw}nav span{color:#a4c6c9;font-size:10px}button{font:inherit;color:inherit;background:#c5e7e811;border:1px solid #c5e7e833;border-radius:99px;padding:7px 12px;cursor:pointer}button[aria-pressed=true]{background:#a2e9da;color:#102923}#note{position:fixed;z-index:2;left:18px;bottom:14px;font:10px ui-monospace;background:#071218cc;padding:7px 10px;border-radius:10px;color:#bdd1d8}</style></head><body><canvas id="arena"></canvas><nav><b>COMBAT LAB / QA FIXTURES</b><button data-test="pulsar">Broken ring</button><button data-test="weaver">Weaver lane</button><button data-test="bulwark">Shield relay</button><button data-test="wall">Corridor wall</button><button id="pauseLab">Resume pattern</button><span>Invulnerable core · durable targets · freezes first discharge</span></nav><div id="note"></div><script>'''+scripts+'''
const canvas=document.querySelector('canvas'),render=FlightRender.create(canvas),keys=new Set();let g,selected='pulsar',running=true,freeze=true,previous=0,aim=null,firing=false;
function preset(type){selected=type;g=Swarm.create(71,{bounds:Swarm.worldSize(innerWidth,innerHeight)});g.round=type==='bulwark'||type==='wall'?4:type==='weaver'?2:0;g.waveStart=100000;g.nextSpawn=g.nextField=Infinity;g.drones=40;g.unlocked=3;g.player.inv=999;g.charge=100;g.salvage=[];g.upgrades={bastion:1,lance:1,rotor:1};const p=g.player;
 const enemy=Swarm.spawn(g,type==='wall'?'sovereign':type,p.x+190,p.y-45);enemy.hp=enemy.max=9000;enemy.born=-1;enemy.ready=0;if(type==='wall')enemy.attackIndex=2;
 if(type==='bulwark'){enemy.dummy=true;for(const dy of [-45,35,80]){const e=Swarm.spawn(g,'sentry',enemy.x+30,enemy.y+dy);e.dummy=true;e.hp=e.max=900;}}
 running=freeze=true;document.querySelector('#pauseLab').textContent='Freeze frame';document.querySelectorAll('[data-test]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.test===type)));
}
document.querySelectorAll('[data-test]').forEach(b=>b.onclick=()=>preset(b.dataset.test));document.querySelector('#pauseLab').onclick=()=>{running=!running;freeze=false;};
addEventListener('keydown',e=>{keys.add(e.key.toLowerCase());if(['1','2','3'].includes(e.key))Swarm.setMode(g,Swarm.modes[+e.key-1]);if(e.code==='Space'){e.preventDefault();Swarm.burst(g);}});addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
canvas.addEventListener('pointermove',e=>{aim=FlightRender.project(FlightRender.camera(g),e.clientX/innerWidth,e.clientY/innerHeight);});canvas.addEventListener('pointerdown',()=>firing=true);addEventListener('pointerup',()=>firing=false);
preset('pulsar');function frame(ms){const dt=Math.min(.05,(ms-previous)/1000||1/60);previous=ms;if(running){for(let n=0;n<Math.max(1,Math.round(dt*60));n++)Swarm.step(g,{aim,fire:firing,x:Number(keys.has('d'))-Number(keys.has('a')),y:Number(keys.has('s'))-Number(keys.has('w'))});if(freeze&&(g.hazards.some(h=>g.t-h.fire>({wave:.65,sweep:1.4,ray:.06}[h.type]??100))||selected==='bulwark'&&g.t>1.8)){running=false;freeze=false;}}
 const ratio=Math.min(2,devicePixelRatio),w=Math.round(innerWidth*ratio),h=Math.round(innerHeight*ratio);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;Swarm.resize(g,Swarm.worldSize(innerWidth,innerHeight));}
 render.draw(g,{dt,wall:g.t,menu:false,reduced:false,frozen:!running,weaponLabel:copy['status'+g.mode[0].toUpperCase()+g.mode.slice(1)].replace('{n}',g.mode==='ring'?g.weapon.guard:g.mode==='spear'?Math.floor(g.weapon.lock*100):(1+g.weapon.spin*.8).toFixed(1))});document.querySelector('#pauseLab').textContent=running?'Freeze frame':'Resume pattern';document.querySelector('#note').textContent=(running?'SIMULATING':'FROZEN DISCHARGE')+' · '+selected+' · '+g.t.toFixed(2)+'s · 1/2/3 formations · WASD move · Mouse aim · hold/release click · Space payload';requestAnimationFrame(frame);}requestAnimationFrame(frame);
</script></body></html>'''
(p/'combat-fixtures.html').write_text(html)
